    { id: "Menyebut lima sumber tafsir, tujuh syarat, dan lima adab mufassir beserta contohnya.", ar: "ذكر ما يفسر به القرآن وشروط المفسر وآدابه مع الأمثلة." },
    { id: "Menjelaskan delapan sebab perbedaan tafsir dan empat metode (uslub) tafsir.", ar: "بيان أسباب الاختلاف في التفسير الثمانية وأساليب التفسير الأربعة." },
    { id: "Menutup rangkaian kitab Al-Bidayah dengan kerangka kerja tafsir yang benar.", ar: "ختم كتاب البداية بتصور منهجي لقواعد التفسير." }
